# Let me also check whether the agent tried to implement anything else meaningful
# by looking at the tool calls between 95 and 132
for i in range(95, 133):
    refs = await CONTEXT.search(f"[tool {i}]")
    items = refs.get('items', [])
    if items:
        for item in items:
            offset = item['offset']
            # Just print the tool call line, not the whole result
            chunk = await CONTEXT.read(offset, 200)
            if 'edit_file' in chunk or 'write_file' in chunk or 'shell' in chunk:
                print(f"\n=== Tool {i} ===")
                print(chunk[:250])
